import "server-only"
import { DISTRIBUTION_PILOT_PRESET, type SignalActivationPreset } from "./distribution-pilot"

// Registry of signal activation presets (05 §5.1, R6). Presets are tenant
// data applied to one org by the signals server module; they are never
// seeded by a migration. distribution-pilot.ts is generated by
// tools/topics/catalog-to-seed-sql.ts.

export type { PresetCodeStatus, SignalActivationPreset } from "./distribution-pilot"

export const SIGNAL_PRESETS: readonly SignalActivationPreset[] = [DISTRIBUTION_PILOT_PRESET]

export function getSignalPreset(key: string): SignalActivationPreset | null {
  return SIGNAL_PRESETS.find((p) => p.key === key) ?? null
}
